      var total := 0;
      var j := 0;
      while j < n
        invariant 0 <= j <= n
        invariant steps <= 4 * n + 1 + 3 * j + 2
        decreases n - j
      {
        total := total + AbsInt(a_list[j]);
        j := j + 1;
        steps := steps + 3;
      }
      ans := total;
    }
    output := IntToString(ans);
    steps := steps + 1;
  }
}

